const D = { scale:1, energy:.6, density:.55, speed:1, strands:5, twist:.5, hue:210, x:.5, y:.5, style:'chromatic', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const t = K.t, sty = P.style, en = P.energy;
const hsh = i => { const s = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return s - Math.floor(s); };
const n = Math.max(3, Math.min(8, Math.round(P.strands)));
const L = Math.max(6, Math.min(16, Math.round(6 + P.density*9)));
const R = L + 3;
const phase = t*(0.22 + P.speed*0.5);
const base = Math.floor(phase), frac = phase - base;
const laneW = width/n, step = height/(R-3);
const xCol = c => laneW*(c+0.5);
const yRow = r => (r - 1 + frac)*step;
const drift = 0.6*Math.sin(t*0.29) + 0.4*Math.sin(t*0.53+1.1);

if (sty==='blueprint') background(214, 58, 18);
else if (sty==='plate') background(36, 11, 57);
else background(226, 34, 9);

// simulate permutation from top down; colour by entry-lane identity
let col = []; for (let e=0;e<n;e++) col[e]=e;
const rowCols = [col.slice()], crosses = [];
for (let r=0;r<R-1;r++){
  const Gg = base - r;
  const c = Math.floor(hsh(Gg*1.73+0.31)*(n-1));
  let e1=-1,e2=-1;
  for (let e=0;e<n;e++){ if(col[e]===c)e1=e; else if(col[e]===c+1)e2=e; }
  const overFirst = hsh(Gg*2.9+4.2) < 0.5;
  col[e1]=c+1; col[e2]=c;
  crosses.push({e1,e2, over: overFirst? e1 : e2});
  rowCols.push(col.slice());
}
const hueOf = e => (P.hue + e*Math.round(320/n) + K.section*8 + drift*6) % 360;
const w = Math.max(2, Math.min(laneW*0.46, laneW*(0.20 + 0.24*en) * (0.55+0.55*P.scale)));
const bass = Math.min(0.5, A.bass*0.6);
strokeCap(ROUND); noFill();

function seg(c0,c1,y0,y1,e,mode){
  const x0=xCol(c0), x1=xCol(c1), my=(y0+y1)/2, hu=hueOf(e);
  if (sty==='blueprint'){
    stroke(200, 65, 30, P.alpha); strokeWeight(w*1.0);
    bezier(x0,y0,x0,my,x1,my,x1,y1);
    stroke(190, 20, 92, P.alpha*0.9); strokeWeight(w*0.30);
    bezier(x0,y0,x0,my,x1,my,x1,y1);
    return;
  }
  if (sty==='plate'){
    stroke(34, 22, 20, P.alpha); strokeWeight(w*(mode==='over'?1.05:0.95));
    bezier(x0,y0,x0,my,x1,my,x1,y1);
    stroke(34, 10, 80, P.alpha*0.4); strokeWeight(w*0.16);
    bezier(x0,y0,x0,my,x1,my,x1,y1);
    return;
  }
  if (sty==='neon'){
    blendMode(ADD);
    stroke(hu,85,32, 30*(P.alpha/100)); strokeWeight(w*1.5);
    bezier(x0,y0,x0,my,x1,my,x1,y1);
    stroke(hu,40,92, 80*(P.alpha/100)); strokeWeight(w*0.42);
    bezier(x0,y0,x0,my,x1,my,x1,y1);
    blendMode(BLEND);
    return;
  }
  // chromatic / rope
  if (mode==='over'){ drawingContext.shadowBlur=w*0.85; drawingContext.shadowColor='rgba(0,0,0,0.5)'; }
  stroke((hu+4)%360, 70, 22+18*(mode==='over'?1:0.6)+10*bass, P.alpha); strokeWeight(w*1.02);
  bezier(x0,y0,x0,my,x1,my,x1,y1);
  drawingContext.shadowBlur=0;
  stroke(hu, 46, 78+12*bass, P.alpha); strokeWeight(w*(sty==='rope'?0.34:0.46));
  bezier(x0,y0,x0,my,x1,my,x1,y1);
  if (sty==='rope'){
    stroke(hu, 20, 96, P.alpha*0.7); strokeWeight(w*0.12);
    bezier(x0+w*0.18,y0,x0+w*0.18,my,x1+w*0.18,my,x1+w*0.18,y1);
  }
}

for (let g=0; g<crosses.length; g++){
  const cr = crosses[g], y0=yRow(g), y1=yRow(g+1);
  for (let e=0;e<n;e++){ if(e!==cr.e1 && e!==cr.e2) seg(rowCols[g][e], rowCols[g+1][e], y0,y1, e, 'straight'); }
  const under = cr.over===cr.e1 ? cr.e2 : cr.e1;
  seg(rowCols[g][under], rowCols[g+1][under], y0,y1, under, 'under');
  seg(rowCols[g][cr.over], rowCols[g+1][cr.over], y0,y1, cr.over, 'over');
}
drawingContext.shadowBlur=0;
blendMode(BLEND);
